// Casos de regresión: prompt + palabras que DEBEN aparecer en la respuesta.
// Añade aquí los casos reales de tu producto.
const casos = [
  { id: 'saludo', prompt: 'Saluda a la clienta María en una sola frase amable en español.', esperado: ['maría'] },
  { id: 'resumen', prompt: 'Resume en una frase: n8n permite automatizar procesos conectando nodos visuales.', esperado: ['n8n'] },
  { id: 'formato-json', prompt: 'Devuelve SOLO un JSON con la clave "ok" con valor true, sin texto extra.', esperado: ['"ok"', 'true'] }
];
return casos.map(function (c) {
  const peticion_ia = {
    model: 'claude-opus-5',
    max_tokens: 512,
    messages: [
      { role: 'user', content: c.prompt }
    ]
  };
  return { json: { id: c.id, prompt: c.prompt, esperado: c.esperado, peticion_ia: peticion_ia } };
});

const caso = $('Casos de prueba').item.json;
const bloques = $json.content || [];
const texto = bloques
  .filter(function (b) { return b.type === 'text'; })
  .map(function (b) { return b.text; })
  .join(' ')
  .toLowerCase();
const ausentes = (caso.esperado || []).filter(function (palabra) {
  return texto.indexOf(String(palabra).toLowerCase()) === -1;
});
return {
  json: {
    id: caso.id,
    pasa: ausentes.length === 0,
    palabras_ausentes: ausentes.join(', '),
    extracto: texto.slice(0, 200)
  }
};

const resultados = $input.all();
const total = resultados.length;
const pasados = resultados.filter(function (r) { return r.json.pasa === true; }).length;
const fallidos = resultados
  .filter(function (r) { return r.json.pasa !== true; })
  .map(function (r) { return r.json.id + ' (faltan: ' + r.json.palabras_ausentes + ')'; });
const UMBRAL_PCT = 80;
const tasa = total > 0 ? Math.round((pasados / total) * 100) : 0;
return [ {
  json: {
    total_casos: total,
    casos_pasados: pasados,
    tasa_exito_pct: tasa,
    umbral_pct: UMBRAL_PCT,
    hay_regresion: tasa < UMBRAL_PCT,
    casos_fallidos: fallidos.join(' | ') || 'ninguno',
    ejecutado_en: new Date().toISOString()
  }
} ];

